class Solution {
public:
    long long makeIntegerBeautiful(long long n, int target) {
        auto get_sum = [](long long x) {
            int s = 0;
            while (x > 0) {
                s += x % 10;
                x /= 10;
            }
            return s;
        };
        if (get_sum(n) <= target) return 0;
        long long orig = n;
        long long base = 10;
        while (get_sum(n) > target) {
            n = (n / base + 1) * base;
            base *= 10;
        }
        return n - orig;
    }
};

class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        if (getSum(n) <= target) return 0;
        long orig = n;
        long base = 10;
        while (getSum(n) > target) {
            n = (n / base + 1) * base;
            base *= 10;
        }
        return n - orig;
    }
    private int getSum(long x) {
        int s = 0;
        while (x > 0) {
            s += (int)(x % 10);
            x /= 10;
        }
        return s;
    }
}

var makeIntegerBeautiful = function(n, target) {
    const getSum = (x) => {
        let s = 0;
        let cur = x;
        while (cur > 0n) {
            s += Number(cur % 10n);
            cur /= 10n;
        }
        return s;
    };
    let curN = BigInt(n);
    const orig = curN;
    const tgt = target;
    if (getSum(curN) <= tgt) return 0;
    let base = 10n;
    while (getSum(curN) > tgt) {
        curN = (curN / base + 1n) * base;
        base *= 10n;
    }
    return Number(curN - orig);
};
